          '"Rasul (Muhammad) beriman kepada apa yang diturunkan kepadanya dari Tuhannya, demikian pula orang-orang yang beriman. Semuanya beriman kepada Allah, malaikat-malaikat-Nya, kitab-kitab-Nya, dan rasul-rasul-Nya. (Mereka berkata), \'Kami tidak membeda-bedakan seorang pun dari rasul-rasul-Nya,\' dan mereka berkata, \'Kami dengar dan kami taat. Ampunilah kami, ya Tuhan kami, dan kepada Engkaulah tempat kembali.\' Allah tidak membebani seseorang melainkan sesuai kesanggupannya. Ia mendapat pahala dari kebajikan yang diusahakannya dan mendapat siksa dari kejahatan yang dikerjakannya. \'Ya Tuhan kami, janganlah Engkau hukum kami jika kami lupa atau tersalah. Ya Tuhan kami, janganlah Engkau bebankan kepada kami beban berat sebagaimana Engkau bebankan kepada orang-orang sebelum kami. Ya Tuhan kami, janganlah Engkau pikulkan kepada kami apa yang tidak sanggup kami memikulnya. Maafkanlah kami, ampunilah kami, dan rahmatilah kami. Engkaulah Pelindung kami, maka tolonglah kami menghadapi kaum yang kafir.\'"',
      sourceId: 'Q.S. Al-Baqarah: 285-286 | Shahih Al-Bukhari 4008, Shahih Muslim 807',
      textUr:
          'رسول ایمان لائے اس پر جو ان کی طرف ان کے رب کی جانب سے نازل کیا گیا اور مومن بھی، سب اللہ پر، اس کے فرشتوں پر، اس کی کتابوں پر اور اس کے رسولوں پر ایمان لائے، (اور کہا) ہم اس کے رسولوں میں سے کسی میں فرق نہیں کرتے، اور انہوں نے کہا ہم نے سنا اور اطاعت کی، اے ہمارے رب! تیری ہی بخشش چاہتے ہیں اور تیری ہی طرف لوٹ کر جانا ہے۔ اللہ کسی جان کو اس کی طاقت سے زیادہ تکلیف نہیں دیتا، جو نیکی کمائی اس کا اسے فائدہ ہے اور جو برائی کمائی اس کا وبال اسی پر ہے، اے ہمارے رب! اگر ہم بھول جائیں یا خطا کریں تو ہمیں نہ پکڑ، اے ہمارے رب! ہم پر ایسا بوجھ نہ ڈال جیسا تو نے ہم سے پہلے لوگوں پر ڈالا تھا، اے ہمارے رب! ہم پر اتنا بوجھ نہ ڈال جتنی ہم میں طاقت نہیں، اور ہم سے درگزر فرما، ہمیں بخش دے اور ہم پر رحم فرما، تو ہی ہمارا مولا ہے، پس کافروں کی قوم کے مقابلے میں ہماری مدد فرما',
      sourceUr: 'سورۃ البقرۃ: 285-286، صحیح بخاری 4008، صحیح مسلم 807',
    ),

