      textUr: 'اللہ وہ ذات ہے جس کے علاوہ کوئی سچا معبود ہمیشہ زندہ رہنے والا اور سب کو قائم رکھنے والا ہے، نہ اسے اونگھ آتی ہے اور نہ نیند، اسی کے لیے ہے جو آسمانوں میں ہے اور جو زمین میں ہے، کون ہے جو اس کی اجازت کے بغیر اس کے پاس سفارش کر سکے، جو لوگوں کے سامنے ہے اور جو ان کے پیچھے ہے سب کو جانتا ہے، لوگ اس کے علم میں سے کسی چیز کا احاطہ نہیں کرسکتے مگر جو وہ چاہے، اسی کی کرسی آسمانوں اور زمین کو گھیرے ہوئے ہے اور ان دونوں کی حفاظت اسے تھکاتی نہیں، اور وہ بلند ہے عظمت والا ہے',
      sourceUr: 'بخاری 2311',
    ),
