      textEn: '"The Messenger believes in what has been sent down to him from his Lord, and so do the believers. Each one believes in Allah, His angels, His books, and His messengers. They say: We make no distinction between any of His messengers. And they say: We hear and we obey; grant us Your forgiveness, our Lord, and to You is the return. Allah does not burden a soul beyond what it can bear. It gets what it earns, and is responsible for what it does. Our Lord, do not hold us accountable if we forget or make a mistake. Our Lord, do not lay upon us a burden like the one You laid on those before us. Our Lord, do not burden us with more than we can bear. Pardon us, forgive us, and have mercy on us. You are our Protector, so grant us victory over the disbelieving people."',
