      textId: '"Rasul (Muhammad) telah beriman kepada apa yang diturunkan kepadanya dari Tuhannya, demikian pula orang-orang yang beriman. Semuanya beriman kepada Allah, malaikat-malaikat-Nya, kitab-kitab-Nya dan rasul-rasul-Nya. Mereka berkata: Kami tidak membeda-bedakan seorang pun dari rasul-rasul-Nya. Dan mereka berkata: Kami dengar dan kami taat. Ampunilah kami ya Tuhan kami, dan kepada Engkaulah tempat kembali. Allah tidak membebani seseorang melainkan sesuai dengan kesanggupannya. Ia mendapat pahala dari kebajikan yang dikerjakannya dan ia mendapat siksa dari kejahatan yang diperbuatnya. Ya Tuhan kami, janganlah Engkau hukum kami jika kami lupa atau kami tersalah. Ya Tuhan kami, janganlah Engkau bebankan kepada kami beban yang berat sebagaimana Engkau bebankan kepada orang-orang sebelum kami. Ya Tuhan kami, janganlah Engkau pikulkan kepada kami apa yang tak sanggup kami memikulnya. Beri maaflah kami, ampunilah kami, dan rahmatilah kami. Engkaulah Penolong kami, maka tolonglah kami terhadap kaum yang kafir." (Q.S. Al-Baqarah: 285-286)',
