      textUr: 'رسول نے اس چیز پر ایمان لایا جو اس کے رب کی طرف سے اس پر نازل ہوئی، اور مومنین نے بھی، سب اللہ اور اس کے فرشتوں اور اس کی کتابوں اور اس کے رسولوں پر ایمان لائے، ہم اس کے رسولوں میں سے کسی کے درمیان فرق نہیں کرتے، اور کہا کہ ہم نے سنا اور اطاعت کی، اے ہمارے رب تیری بخشش چاہتے ہیں اور تیری ہی طرف لوٹنا ہے۔ اللہ کسی کو اس کی طاقت سے زیادہ تکلیف نہیں دیتا، ہر ایک کو اس کی کمائی کا اچھا اور برا پھل ملے گا، اے ہمارے رب اگر ہم بھول جائیں یا خطا کریں تو ہمیں نہ پکڑ، اے ہمارے رب ہم پر وہ بوجھ نہ ڈال جو تو نے ہم سے پہلے لوگوں پر ڈالا تھا، اے ہمارے رب ہم پر وہ بوجھ نہ ڈال جس کی ہمیں طاقت نہ ہو، اور ہم سے درگزر فرما اور ہمیں بخش دے اور ہم پر رحم فرما، تو ہی ہمارا مولیٰ ہے، پس کافروں کے مقابلے میں ہماری مدد فرما',
