      textEn: '"Indeed, in the creation of the heavens and the earth, and the alternation of night and day, are signs for people of understanding — those who remember Allah while standing, sitting, or lying on their sides, and reflect on the creation of the heavens and the earth: Our Lord, You did not create this without purpose; glory be to You, so protect us from the punishment of the Fire. Our Lord, whoever You admit into the Fire, You have surely disgraced, and the wrongdoers will have no helpers. Our Lord, we heard a caller calling to faith, saying: Believe in your Lord, so we believed. Our Lord, forgive us our sins, remove from us our misdeeds, and let us die with the righteous. Our Lord, grant us what You promised us through Your messengers, and do not disgrace us on the Day of Resurrection; You never break Your promise."',
      sourceEn: 'Al-Bukhari 183, Muslim 763',
      textId: '"Sesungguhnya dalam penciptaan langit dan bumi, dan silih bergantinya malam dan siang, terdapat tanda-tanda bagi orang-orang yang berakal, (yaitu) orang-orang yang mengingat Allah sambil berdiri atau duduk atau dalam keadaan berbaring dan mereka memikirkan tentang penciptaan langit dan bumi (seraya berkata): Ya Tuhan kami, tiadalah Engkau menciptakan ini dengan sia-sia, Maha Suci Engkau, maka peliharalah kami dari siksa neraka. Ya Tuhan kami, sesungguhnya barangsiapa yang Engkau masukkan ke dalam neraka, maka sungguh telah Engkau hinakan ia, dan tidak ada bagi orang-orang yang zalim seorang penolong pun. Ya Tuhan kami, sesungguhnya kami mendengar (seruan) yang menyeru kepada iman, (yaitu): Berimanlah kamu kepada Tuhanmu, maka kamipun beriman. Ya Tuhan kami, ampunilah bagi kami dosa-dosa kami dan hapuskanlah dari kami kesalahan-kesalahan kami, dan wafatkanlah kami beserta orang-orang yang berbakti. Ya Tuhan kami, berilah kami apa yang telah Engkau janjikan kepada kami dengan perantaraan rasul-rasul Engkau. Dan janganlah Engkau hinakan kami di hari kiamat. Sesungguhnya Engkau tidak menyalahi janji." (Q.S. Ali Imran: 190-194)',
