      textEn: '"Allah! There is no god but He, the Ever-Living, the Sustainer of all existence. Neither slumber nor sleep overtakes Him. To Him belongs all that is in the heavens and all that is on the earth. Who can intercede with Him except by His permission? He knows what is before them and what is behind them, and they encompass nothing of His knowledge except what He wills. His Kursi extends over the heavens and the earth, and preserving them tires Him not. He is the Most High, the Most Great."',
      sourceEn: 'Hisn al-Muslim',
      textId: '"Allah, tidak ada Tuhan (yang berhak disembah) melainkan Dia, yang hidup kekal lagi terus menerus, mengurus (makhluk-Nya), tidak mengantuk dan tidak tidur. Kepunyaan-Nya apa yang di langit dan di bumi, tiada yang dapat memberi syafa\'at di sisi Allah tanpa seizin-Nya. Allah mengetahui apa-apa yang di hadapan mereka dan di belakang mereka, dan mereka tidak mengetahui apa-apa dari ilmu Allah melainkan apa yang dikehendaki-Nya. Kursi Allah meliputi langit dan bumi dan Allah tidak merasa berat memelihara keduanya, dan Allah Maha Tinggi lagi Maha Besar." (Q.S. Al-Baqarah: 255)',
      sourceId: 'Hisn al-Muslim',
      textUr: 'اللہ وہ ذات ہے جس کے علاوہ کوئی سچا معبود ہمیشہ زندہ رہنے والا اور سب کو قائم رکھنے والا ہے، نہ اسے اونگھ آتی ہے اور نہ نیند، اسی کے لیے ہے جو آسمانوں میں ہے اور جو زمین میں ہے، کون ہے جو اس کی اجازت کے بغیر اس کے پاس سفارش کر سکے، جو لوگوں کے سامنے ہے اور جو ان کے پیچھے ہے سب کو جانتا ہے، لوگ اس کے علم میں سے کسی چیز کا احاطہ نہیں کرسکتے مگر جو وہ چاہے، اسی کی کرسی آسمانوں اور زمین کو گھیرے ہوئے ہے اور ان دونوں کی حفاظت اسے تھکاتی نہیں، اور وہ بلند ہے عظمت والا ہے',
      sourceUr: 'حصن المسلم',
    ),
