      text:
          'آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ وَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ (285)\nلَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا أَنْتَ مَوْلَانَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ (286)',
      source: 'سورة البقرة: الآيتان (285-286)',
      bookSource: 'القرآن الكريم',
      virtue: 'من قرأهما في ليلة كفتاه (أي كفتاه من قيام الليل، وقيل: من كل سوء ومكروه)',
      count: 1,
      category: DhikrCategory.ruqyah,
      textEn: '"The Messenger has believed in what was revealed to him from his Lord, and so have the believers. All of them have believed in Allah and His angels and His books and His messengers, [saying], We make no distinction between any of His messengers. And they say: We hear and we obey; [we seek] Your forgiveness, our Lord, and to You is the [final] destination. Allah does not charge a soul except with that within its capacity. It will have [the consequence of] what good it has gained, and it will bear what evil it has earned. Our Lord, do not impose blame upon us if we forget or make a mistake. Our Lord, and lay not upon us a burden like that which You laid upon those before us. Our Lord, and burden us not with that which we have no ability to bear. And pardon us, forgive us, and have mercy upon us; You are our Protector, so give us victory over the disbelieving people." (Al-Baqarah 285-286)',
      sourceEn: 'Hisn al-Muslim',
      textId: '"Rasul telah beriman kepada Al-Qur\'an yang diturunkan kepadanya dari Tuhannya, demikian pula orang-orang yang beriman. Semuanya beriman kepada Allah, malaikat-malaikat-Nya, kitab-kitab-Nya dan rasul-rasul-Nya. (Mereka berkata): Kami tidak membeda-bedakan seorang pun dari rasul-rasul-Nya. Dan mereka berkata: Kami dengar dan kami taat. (Mereka berdoa): Ampunilah kami ya Tuhan kami dan kepada Engkaulah tempat kembali. Allah tidak membebani seseorang melainkan sesuai dengan kesanggupannya. Ia mendapat pahala dari (kebajikan) yang diusahakannya dan ia mendapat siksa dari (kejahatan) yang dikerjakannya. Ya Tuhan kami, janganlah Engkau hukum kami jika kami lupa atau kami tersalah. Ya Tuhan kami, janganlah Engkau bebankan kepada kami beban yang berat sebagaimana Engkau bebankan kepada orang-orang sebelum kami. Ya Tuhan kami, janganlah Engkau pikulkan kepada kami apa yang tak sanggup kami memikulnya. Beri maaflah kami, ampunilah kami, dan rahmatilah kami. Engkaulah Penolong kami, maka tolonglah kami terhadap kaum yang kafir." (Q.S. Al-Baqarah: 285-286)',
      sourceId: 'Hisn al-Muslim',
      textUr: 'رسول اس چیز پر ایمان لایا جو اس کے رب کی طرف سے اس پر نازل ہوئی اور مومن بھی ایمان لائے، سب اللہ پر اور اس کے فرشتوں پر اور اس کی کتابوں پر اور اس کے رسولوں پر ایمان لائے، وہ کہتے ہیں کہ ہم اس کے رسولوں میں سے کسی میں فرق نہیں کرتے، اور کہتے ہیں ہم نے سنا اور اطاعت کی، اے ہمارے رب تیری ہی بخشش چاہتے ہیں اور تیری ہی طرف لوٹنا ہے۔ اللہ کسی جان کو اس کی طاقت سے زیادہ ذمہ دار نہیں بناتا، اسے وہی ملے گا جو اس نے کمایا اور اسی پر ہے جو اس نے کمایا، اے ہمارے رب اگر ہم بھول جائیں یا خطا کریں تو ہمیں نہ پکڑ، اے ہمارے رب ہم پر وہ بوجھ نہ ڈال جو تو نے ہم سے پہلے لوگوں پر ڈالا تھا، اے ہمارے رب ہم پر وہ بوجھ نہ ڈال جس کی ہمیں طاقت نہیں، اور ہم سے درگزر فرما، ہمیں بخش دے اور ہم پر رحم فرما، تو ہی ہمارا کارساز ہے، پس کافروں کی قوم پر ہماری مدد فرما',
      sourceUr: 'حصن المسلم',
