      text: 'بَيْنَما نَحْنُ جُلُوسٌ عِنْدَ رَسُولِ اللَّهِ ﷺ ذاتَ يَوْمٍ، إذْ طَلَعَ عَلَيْنا رَجُلٌ شَدِيدُ بَياضِ الثِّيابِ، شَدِيدُ سَوادِ الشَّعْرِ، لا يُرَى عَلَيْهِ أَثَرُ السَّفَرِ، وَلا يَعْرِفُهُ مِنّا أَحَدٌ. حَتَّى جَلَسَ إلَى النَّبِيِّ ﷺ، فَأَسْنَدَ رُكْبَتَيْهِ إلَى رُكْبَتَيْهِ، وَوَضَعَ كَفَّيْهِ عَلَى فَخْذَيْهِ، وَقالَ: يا مُحَمَّدُ أَخْبِرْنِي عَنِ الإِسْلامِ. فَقالَ رَسُولُ اللَّهِ ﷺ: الإِسْلامُ أَنْ تَشْهَدَ أَنْ لا إلَهَ إلّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَتُقِيمَ الصَّلاةَ، وَتُؤْتِيَ الزَّكاةَ، وَتَصُومَ رَمَضانَ، وَتَحُجَّ البَيْتَ إنِ اسْتَطَعْتَ إلَيْهِ سَبِيلًا. قالَ: صَدَقْتَ. فَعَجِبْنا لَهُ يَسْأَلُهُ وَيُصَدِّقُهُ! قالَ: فَأَخْبِرْنِي عَنِ الإِيمانِ. قالَ: أَنْ تُؤْمِنَ بِاللَّهِ وَمَلائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَالْيَوْمِ الآخِرِ، وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ. قالَ: صَدَقْتَ. قالَ: فَأَخْبِرْنِي عَنِ الإِحْسانِ. قالَ: أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَراهُ، فَإِنْ لَمْ تَكُنْ تَراهُ فَإِنَّهُ يَراكَ. قالَ: فَأَخْبِرْنِي عَنِ السّاعَةِ. قالَ: ما المَسْئُولُ عَنْها بِأَعْلَمَ مِنَ السّائِلِ. قالَ: فَأَخْبِرْنِي عَنْ أَماراتِها؟ قالَ: أَنْ تَلِدَ الأَمَةُ رَبَّتَها، وَأَنْ تَرَى الحُفاةَ العُراةَ العالَةَ رِعاءَ الشّاءِ يَتَطاوَلُونَ فِي البُنْيانِ. ثُمَّ انْطَلَقَ، فَلَبِثْتُ مَلِيًّا، ثُمَّ قالَ: يا عُمَرُ أَتَدْرِي مَنِ السّائِلُ؟ قُلْتُ: اللَّهُ وَرَسُولُهُ أَعْلَمُ. قالَ: فَإِنَّهُ جِبْرِيلُ أَتاكُمْ يُعَلِّمُكُمْ دِينَكُمْ.',
      source: 'عن عمر بن الخطاب رضي الله عنه — رواه مسلم',
      bookSource: 'الأربعون النووية للإمام النووي',
      virtue: 'أركان الإسلام والإيمان والإحسان',
      count: 1,
      category: DhikrCategory.nawawi40,
      textEn: 'One day while we were sitting with the Messenger of Allah ﷺ, a man in pure white clothes and jet-black hair appeared, showing no signs of travel, and none of us recognized him. He sat before the Prophet ﷺ, placed his hands on his thighs, and said: "O Muhammad, tell me about Islam." The Prophet ﷺ said: "Islam is to testify that there is no god but Allah and that Muhammad is His Messenger, to establish prayer, pay zakat, fast Ramadan, and perform Hajj if able." He said, "You have spoken the truth" — we were amazed that he asked and then confirmed the answer. He asked about faith (iman), and the Prophet ﷺ said it is to believe in Allah, His angels, His books, His messengers, the Last Day, and in divine decree, both good and bad. He asked about excellence (ihsan), and the Prophet ﷺ said it is to worship Allah as though you see Him, for even though you do not see Him, He sees you. He then asked about the Hour, and the Prophet ﷺ said the one asked knows no more than the one asking, but described some of its signs. The man then left, and after a while the Prophet ﷺ asked: "Do you know who the questioner was?" We said Allah and His Messenger know best. He said: "That was Gabriel, who came to teach you your religion."',
      sourceEn: 'Riyad as-Salihin / An-Nawawi\'s Forty Hadith',
      textId: 'Suatu hari ketika kami duduk bersama Rasulullah ﷺ, tiba-tiba muncul seorang laki-laki berpakaian sangat putih dan berambut sangat hitam, tidak tampak padanya tanda-tanda bekas perjalanan, dan tidak seorang pun dari kami yang mengenalnya. Ia duduk di hadapan Nabi ﷺ dan meletakkan kedua tangannya di atas kedua pahanya, lalu berkata: "Wahai Muhammad, beritahu aku tentang Islam." Rasulullah ﷺ bersabda: "Islam adalah engkau bersaksi bahwa tidak ada Tuhan selain Allah dan Muhammad adalah utusan Allah, mendirikan salat, menunaikan zakat, berpuasa Ramadan, dan berhaji ke Baitullah jika mampu." Ia berkata: "Engkau benar" — kami heran, ia bertanya namun juga membenarkan jawabannya! Ia bertanya tentang iman, Nabi ﷺ menjawab: percaya kepada Allah, malaikat-malaikat-Nya, kitab-kitab-Nya, rasul-rasul-Nya, hari akhir, dan takdir baik maupun buruk. Ia bertanya tentang ihsan, Nabi ﷺ menjawab: engkau menyembah Allah seakan-akan melihat-Nya, jika engkau tidak melihat-Nya maka sesungguhnya Dia melihatmu. Ia bertanya tentang hari kiamat, Nabi ﷺ menjawab bahwa yang ditanya tidak lebih tahu dari yang bertanya, namun menyebutkan sebagian tandanya. Lelaki itu kemudian pergi, dan setelah beberapa saat Nabi ﷺ bertanya: "Tahukah engkau siapa penanya tadi?" Kami menjawab Allah dan Rasul-Nya lebih tahu. Beliau bersabda: "Itu adalah Jibril yang datang untuk mengajarkan agama kepada kalian."',
      sourceId: 'Riyadhus Shalihin / Hadis Arbain An-Nawawi',
      textUr: 'ایک دن جب ہم رسول اللہ ﷺ کے پاس بیٹھے تھے، اچانک ایک شخص نمودار ہوا جس کے کپڑے سفید اور بال کالے تھے، اس پر سفر کے کوئی آثار نہ تھے اور ہم میں سے کوئی اسے نہیں جانتا تھا۔ وہ نبی ﷺ کے پاس بیٹھ گیا اور اپنے ہاتھ اپنی رانوں پر رکھ کر کہا: اے محمد! مجھے اسلام کے بارے میں بتائیں۔ نبی ﷺ نے فرمایا: اسلام یہ ہے کہ تم گواہی دو کہ اللہ کے سوا کوئی معبود نہیں اور محمد اللہ کے رسول ہیں، نماز قائم کرو، زکوٰۃ دو، رمضان کے روزے رکھو، اور اگر استطاعت ہو تو بیت اللہ کا حج کرو۔ اس نے کہا: آپ نے سچ کہا۔ ہمیں تعجب ہوا کہ وہ سوال بھی کرتا ہے اور تصدیق بھی۔ پھر اس نے ایمان کے بارے میں پوچھا، نبی ﷺ نے فرمایا: اللہ، اس کے فرشتوں، کتابوں، رسولوں، آخرت کے دن اور اچھی بری تقدیر پر ایمان لانا۔ پھر احسان کے بارے میں پوچھا، فرمایا: اللہ کی عبادت اس طرح کرو گویا تم اسے دیکھ رہے ہو، اگر تم اسے نہیں دیکھتے تو وہ تمہیں دیکھ رہا ہے۔ پھر قیامت کے بارے میں پوچھا، نبی ﷺ نے فرمایا کہ جس سے پوچھا جا رہا ہے وہ پوچھنے والے سے زیادہ نہیں جانتا، البتہ کچھ علامات بتائیں۔ پھر وہ شخص چلا گیا، کچھ دیر بعد نبی ﷺ نے پوچھا: عمر! جانتے ہو یہ سوال کرنے والا کون تھا؟ میں نے کہا اللہ اور اس کا رسول بہتر جانتے ہیں۔ فرمایا: یہ جبریل تھے جو تمہیں تمہارا دین سکھانے آئے تھے',
      sourceUr: 'ریاض الصالحین / اربعین نووی',
    ),
