      category: DhikrCategory.nawawi40,
      textEn: 'The Messenger of Allah ﷺ, the truthful and trusted one, told us: Each of you is formed in your mother\'s womb for forty days as a drop, then a clot for the same period, then a lump of flesh for the same period. Then an angel is sent to breathe the soul into it, and is commanded to write four things: its provision, its lifespan, its deeds, and whether it will be wretched or blessed. By Allah besides whom there is no god, one of you may do the deeds of the people of Paradise until there is only an arm\'s length between him and it, then what is written overtakes him and he does the deeds of the people of the Fire and enters it. And one of you may do the deeds of the people of the Fire until there is only an arm\'s length between him and it, then what is written overtakes him and he does the deeds of the people of Paradise and enters it.',
      sourceEn: 'Riyad as-Salihin / An-Nawawi\'s Forty Hadith',
      textId: 'Rasulullah ﷺ, yang jujur dan terpercaya, menceritakan kepada kami: Sesungguhnya penciptaan salah seorang dari kalian dikumpulkan dalam rahim ibunya selama empat puluh hari berupa nutfah (setetes mani), kemudian menjadi segumpal darah selama itu juga, kemudian menjadi segumpal daging selama itu juga, kemudian diutus kepadanya seorang malaikat untuk meniupkan ruh kepadanya, dan diperintahkan untuk menulis empat perkara: rezekinya, ajalnya, amalnya, serta celaka atau bahagianya. Demi Allah yang tidak ada Tuhan selain Dia, sesungguhnya salah seorang dari kalian benar-benar mengerjakan amalan penghuni surga hingga jarak antara dirinya dengan surga tinggal sehasta, namun catatan takdir mendahuluinya sehingga ia mengerjakan amalan penghuni neraka lalu masuk ke dalamnya. Dan sesungguhnya salah seorang dari kalian benar-benar mengerjakan amalan penghuni neraka hingga jarak antara dirinya dengan neraka tinggal sehasta, namun catatan takdir mendahuluinya sehingga ia mengerjakan amalan penghuni surga lalu masuk ke dalamnya.',
