      text: 'عَنِ النَّبِيِّ صلى الله عليه وسلم فِيما يَرْوِيهِ عَنْ رَبِّهِ عَزَّ وَجَلَّ أَنَّهُ قالَ: يا عِبادِي إنِّي حَرَّمْتُ الظُّلْمَ عَلَى نَفْسِي وَجَعَلْتُهُ بَيْنَكُمْ مُحَرَّمًا فَلا تَظالَمُوا، يا عِبادِي كُلُّكُمْ ضالٌّ إلّا مَنْ هَدَيْتُهُ فاسْتَهْدُونِي أَهْدِكُمْ، يا عِبادِي كُلُّكُمْ جائِعٌ إلّا مَنْ أَطْعَمْتُهُ فاسْتَطْعِمُونِي أُطْعِمْكُمْ، يا عِبادِي كُلُّكُمْ عارٍ إلّا مَنْ كَسَوْتُهُ فاسْتَكْسُونِي أَكْسُكُمْ، يا عِبادِي إنَّكُمْ تُخْطِئُونَ بِاللَّيْلِ وَالنَّهارِ وَأَنا أَغْفِرُ الذُّنُوبَ جَمِيعًا فاسْتَغْفِرُونِي أَغْفِرْ لَكُمْ، يا عِبادِي إنَّكُمْ لَنْ تَبْلُغُوا ضُرِّي فَتَضُرُّونِي وَلَنْ تَبْلُغُوا نَفْعِي فَتَنْفَعُونِي، يا عِبادِي لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ كانُوا عَلَى أَتْقَى قَلْبِ رَجُلٍ واحِدٍ مِنْكُمْ ما زادَ ذَلِكَ فِي مُلْكِي شَيْئًا، يا عِبادِي لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ كانُوا عَلَى أَفْجَرِ قَلْبِ رَجُلٍ واحِدٍ مِنْكُمْ ما نَقَصَ ذَلِكَ مِنْ مُلْكِي شَيْئًا، يا عِبادِي لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ قامُوا فِي صَعِيدٍ واحِدٍ فَسَأَلُونِي فَأَعْطَيْتُ كُلَّ واحِدٍ مَسْأَلَتَهُ ما نَقَصَ ذَلِكَ مِمّا عِنْدِي إلّا كَما يَنْقُصُ المِخْيَطُ إذا أُدْخِلَ البَحْرَ، يا عِبادِي إنَّما هِيَ أَعْمالُكُمْ أُحْصِيها لَكُمْ ثُمَّ أُوَفِّيكُمْ إيّاها، فَمَنْ وَجَدَ خَيْرًا فَلْيَحْمَدِ اللَّهَ، وَمَنْ وَجَدَ غَيْرَ ذَلِكَ فَلا يَلُومَنَّ إلّا نَفْسَهُ.',
      source: 'عن أبو ذر الغفاري رضي الله عنه — رواه مسلم',
      bookSource: 'الأربعون النووية للإمام النووي',
      virtue: 'تحريم الظلم وسعة رحمة الله وغناه عن خلقه',
      count: 1,
      category: DhikrCategory.nawawi40,
      textEn: 'The Prophet ﷺ related from his Lord, who said: "O My servants, I have forbidden oppression for Myself and made it forbidden among you, so do not oppress one another. O My servants, all of you are astray except those I guide, so seek guidance from Me and I will guide you. O My servants, all of you are hungry except those I feed, so seek food from Me and I will feed you. O My servants, all of you are naked except those I clothe, so seek clothing from Me and I will clothe you. O My servants, you sin by night and day, and I forgive all sins, so seek My forgiveness and I will forgive you. O My servants, you could never harm Me nor benefit Me. O My servants, even if the first and last of you, humans and jinn, were as pious as the most pious heart among you, it would not add anything to My dominion. O My servants, even if the first and last of you were as wicked as the most wicked heart among you, it would not diminish My dominion at all. O My servants, if the first and last of you, humans and jinn, all stood on one plain and asked Me, and I gave everyone what they asked, it would not decrease what I have any more than a needle decreases the ocean when dipped into it. O My servants, it is only your deeds that I record for you and then repay you in full — so let whoever finds good praise Allah, and whoever finds otherwise blame only himself."',
      sourceEn: 'Riyad as-Salihin / An-Nawawi\'s Forty Hadith',
      textId: 'Nabi ﷺ meriwayatkan dari Tuhannya, Dia berfirman: "Wahai hamba-hamba-Ku, sesungguhnya Aku telah mengharamkan kezaliman atas diri-Ku dan Aku jadikan ia haram di antara kalian, maka janganlah saling menzalimi. Wahai hamba-hamba-Ku, kalian semua sesat kecuali yang Aku beri petunjuk, maka mintalah petunjuk kepada-Ku niscaya Aku akan memberi kalian petunjuk. Wahai hamba-hamba-Ku, kalian semua lapar kecuali yang Aku beri makan, maka mintalah makan kepada-Ku niscaya Aku akan memberi kalian makan. Wahai hamba-hamba-Ku, kalian semua telanjang kecuali yang Aku beri pakaian, maka mintalah pakaian kepada-Ku niscaya Aku akan memberi kalian pakaian. Wahai hamba-hamba-Ku, sesungguhnya kalian berbuat salah siang dan malam, dan Aku mengampuni semua dosa, maka mintalah ampun kepada-Ku niscaya Aku akan mengampuni kalian. Wahai hamba-hamba-Ku, kalian tidak akan pernah bisa mencelakai-Ku ataupun memberi manfaat kepada-Ku. Wahai hamba-hamba-Ku, seandainya orang pertama dan terakhir dari kalian, manusia dan jin, semuanya memiliki hati sebaik hati orang yang paling bertakwa di antara kalian, itu tidak akan menambah kerajaan-Ku sedikit pun. Wahai hamba-hamba-Ku, seandainya orang pertama dan terakhir dari kalian memiliki hati sejahat hati orang yang paling durhaka di antara kalian, itu tidak akan mengurangi kerajaan-Ku sedikit pun. Wahai hamba-hamba-Ku, seandainya orang pertama dan terakhir dari kalian, manusia dan jin, berdiri di satu tempat lalu meminta kepada-Ku, dan Aku memberi setiap orang apa yang dimintanya, itu tidak akan mengurangi apa yang ada pada-Ku kecuali seperti berkurangnya air laut ketika dicelupkan sebuah jarum ke dalamnya. Wahai hamba-hamba-Ku, sesungguhnya itu hanyalah amal perbuatan kalian yang Aku catat untuk kalian kemudian Aku balas secara penuh, maka barangsiapa mendapati kebaikan hendaklah ia memuji Allah, dan barangsiapa mendapati selain itu janganlah ia mencela kecuali dirinya sendiri."',
      sourceId: 'Riyadhus Shalihin / Hadis Arbain An-Nawawi',
      textUr: 'نبی ﷺ نے اپنے رب سے روایت کی، اس نے فرمایا: اے میرے بندو! میں نے ظلم کو اپنے اوپر حرام کر لیا ہے اور اسے تمہارے درمیان بھی حرام کر دیا ہے، لہٰذا آپس میں ظلم نہ کرو۔ اے میرے بندو! تم سب گمراہ ہو سوائے اس کے جسے میں ہدایت دوں، پس مجھ سے ہدایت مانگو میں تمہیں ہدایت دوں گا۔ اے میرے بندو! تم سب بھوکے ہو سوائے اس کے جسے میں کھلاؤں، پس مجھ سے کھانا مانگو میں تمہیں کھلاؤں گا۔ اے میرے بندو! تم سب ننگے ہو سوائے اس کے جسے میں پہناؤں، پس مجھ سے لباس مانگو میں تمہیں پہناؤں گا۔ اے میرے بندو! تم رات دن گناہ کرتے ہو اور میں سارے گناہ بخش دیتا ہوں، پس مجھ سے بخشش مانگو میں تمہیں بخش دوں گا۔ اے میرے بندو! تم مجھے نہ نقصان پہنچا سکتے ہو نہ فائدہ۔ اے میرے بندو! اگر تم میں سے پہلے اور آخری، انسان اور جن سب کے دل سب سے متقی شخص کے دل جیسے ہو جائیں تو اس سے میری بادشاہت میں کچھ اضافہ نہیں ہوگا۔ اے میرے بندو! اگر تم سب کے دل سب سے بدکار شخص کے دل جیسے ہو جائیں تو اس سے میری بادشاہت میں کوئی کمی نہیں آئے گی۔ اے میرے بندو! اگر تم سب ایک میدان میں جمع ہو کر مجھ سے مانگو اور میں ہر ایک کو اس کی مانگ دے دوں تو اس سے میرے پاس جو ہے اس میں اتنی ہی کمی آئے گی جتنی سوئی کو سمندر میں ڈبونے سے پانی میں آتی ہے۔ اے میرے بندو! یہ تو صرف تمہارے اعمال ہیں جنہیں میں تمہارے لیے شمار کرتا ہوں پھر تمہیں پورا پورا بدلہ دیتا ہوں، پس جو بھلائی پائے وہ اللہ کی حمد کرے، اور جو اس کے علاوہ پائے وہ صرف اپنے آپ کو ملامت کرے',
      sourceUr: 'ریاض الصالحین / اربعین نووی',
    ),
    const DhikrModel(
      title: 'الحديث 25: كل عمل خير صدقة ولو بغير مال',
      text: 'أَنَّ ناسًا مِنْ أَصْحابِ رَسُولِ اللَّهِ صلى الله عليه وسلم قالُوا لِلنَّبِيِّ صلى الله عليه وسلم: يا رَسُولَ اللَّهِ ذَهَبَ أَهْلُ الدُّثُورِ بِالأُجُورِ، يُصَلُّونَ كَما نُصَلِّي، وَيَصُومُونَ كَما نَصُومُ، وَيَتَصَدَّقُونَ بِفُضُولِ أَمْوالِهِمْ، قالَ: أَوَلَيْسَ قَدْ جَعَلَ اللَّهُ لَكُمْ ما تَصَّدَّقُونَ؟ إنَّ بِكُلِّ تَسْبِيحَةٍ صَدَقَةً، وَكُلِّ تَكْبِيرَةٍ صَدَقَةً، وَكُلِّ تَحْمِيدَةٍ صَدَقَةً، وَكُلِّ تَهْلِيلَةٍ صَدَقَةً، وَأَمْرٌ بِالمَعْرُوفِ صَدَقَةٌ، وَنَهْيٌ عَنْ مُنْكَرٍ صَدَقَةٌ، وَفِي بُضْعِ أَحَدِكُمْ صَدَقَةٌ، قالُوا: يا رَسُولَ اللَّهِ أَيَأْتِي أَحَدُنا شَهْوَتَهُ وَيَكُونُ لَهُ فِيها أَجْرٌ؟ قالَ: أَرَأَيْتُمْ لَوْ وَضَعَها فِي حَرامٍ أَكانَ عَلَيْهِ وِزْرٌ؟ فَكَذَلِكَ إذا وَضَعَها فِي الحَلالِ كانَ لَهُ أَجْرٌ.',
      source: 'عن أبو ذر رضي الله عنه — رواه مسلم',
