      category: DhikrCategory.nawawi40,
      textEn: 'Some of the companions said to the Prophet ﷺ, "O Messenger of Allah, the wealthy have taken all the reward — they pray as we pray, fast as we fast, and give charity from their surplus wealth." He said, "Has Allah not made things for you to give in charity? Every glorification of Allah is charity, every declaration of His greatness is charity, every praise of Him is charity, every proclamation of His oneness is charity, enjoining good is charity, forbidding wrong is charity, and even intimacy with your spouse is charity." They asked, "O Messenger of Allah, will one of us have a reward for fulfilling his desire?" He said, "Do you not see that if he had satisfied it unlawfully, he would have been sinning? Likewise, if he satisfies it lawfully, he will have a reward."',
      sourceEn: 'Riyad as-Salihin / An-Nawawi\'s Forty Hadith',
      textId: 'Sebagian sahabat Rasulullah ﷺ berkata kepada beliau: "Wahai Rasulullah, orang-orang kaya telah pergi membawa banyak pahala, mereka salat seperti kami salat, berpuasa seperti kami berpuasa, dan mereka bersedekah dengan kelebihan harta mereka." Beliau bersabda: "Bukankah Allah telah menjadikan bagi kalian sesuatu untuk bersedekah? Sesungguhnya setiap tasbih adalah sedekah, setiap takbir adalah sedekah, setiap tahmid adalah sedekah, setiap tahlil adalah sedekah, menyuruh kepada kebaikan adalah sedekah, mencegah kemungkaran adalah sedekah, bahkan hubungan suami istri kalian adalah sedekah." Mereka bertanya: "Wahai Rasulullah, apakah salah seorang dari kami memenuhi syahwatnya lalu ia mendapat pahala?" Beliau bersabda: "Bagaimana pendapat kalian jika ia menyalurkannya pada yang haram, bukankah ia berdosa? Demikian pula jika ia menyalurkannya pada yang halal, maka ia mendapat pahala."',
      sourceId: 'Riyadhus Shalihin / Hadis Arbain An-Nawawi',
      textUr: 'صحابہ نے نبی ﷺ سے کہا: اے اللہ کے رسول! مالدار لوگ سارا ثواب لے گئے، وہ ہماری طرح نماز پڑھتے ہیں، ہماری طرح روزہ رکھتے ہیں، اور اپنے فاضل مال سے صدقہ بھی کرتے ہیں۔ آپ ﷺ نے فرمایا: کیا اللہ نے تمہارے لیے صدقہ کرنے کی چیزیں نہیں بنائیں؟ ہر تسبیح صدقہ ہے، ہر تکبیر صدقہ ہے، ہر تحمید صدقہ ہے، ہر تہلیل صدقہ ہے، نیکی کا حکم دینا صدقہ ہے، برائی سے روکنا صدقہ ہے، اور تمہارا اپنی بیوی سے تعلق بھی صدقہ ہے۔ صحابہ نے پوچھا: اے اللہ کے رسول! کیا ہم میں سے کوئی اپنی خواہش پوری کرے تو اسے اس پر ثواب ملے گا؟ آپ ﷺ نے فرمایا: بتاؤ اگر وہ اسے حرام طریقے سے پورا کرتا تو کیا گناہ نہ ہوتا؟ اسی طرح جب وہ اسے حلال طریقے سے پورا کرے تو اسے ثواب ملتا ہے',
      sourceUr: 'ریاض الصالحین / اربعین نووی',
