      title: 'الحديث 27: معيار البر والإثم في اطمئنان القلب',
      text: 'عَنِ النَّوّاسِ بْنِ سَمْعانَ رضي الله عنه عَنِ النَّبِيِّ صلى الله عليه وسلم قالَ: البِرُّ حُسْنُ الخُلُقِ، وَالإِثْمُ ما حاكَ فِي صَدْرِكَ وَكَرِهْتَ أَنْ يَطَّلِعَ عَلَيْهِ النّاسُ. وَعَنْ وابِصَةَ بْنِ مَعْبَدٍ رضي الله عنه قالَ: أَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَقالَ: جِئْتَ تَسْأَلُ عَنِ البِرِّ؟ قُلْتُ: نَعَمْ. فَقالَ: اسْتَفْتِ قَلْبَكَ؛ البِرُّ ما اطْمَأَنَّتْ إلَيْهِ النَّفْسُ وَاطْمَأَنَّ إلَيْهِ القَلْبُ، وَالإِثْمُ ما حاكَ فِي النَّفْسِ وَتَرَدَّدَ فِي الصَّدْرِ، وَإِنْ أَفْتاكَ النّاسُ وَأَفْتَوْكَ.',
      source: 'عن النواس بن سمعان رضي الله عنه، ووابصة بن معبد رضي الله عنه — الأول رواه مسلم، والثاني حديث حسن رويناه في مسندي الإمامين أحمد بن حنبل والدارمي بإسناد حسن',
      bookSource: 'الأربعون النووية للإمام النووي',
      virtue: 'معيار البر والإثم في اطمئنان القلب',
      count: 1,
      category: DhikrCategory.nawawi40,
      textEn: 'An-Nawwas ibn Sam\'an reported the Prophet ﷺ said: "Righteousness is good character, and sin is what stirs uneasily in your soul and which you dislike people finding out about." And Wabisah ibn Ma\'bad reported: I came to the Messenger of Allah ﷺ and he said, "You have come to ask about righteousness?" I said yes. He said, "Consult your heart. Righteousness is that about which the soul feels tranquil and the heart feels tranquil, and sin is that which wavers in the soul and causes uneasiness in the chest, even if people repeatedly give you a ruling in its favor."',
      sourceEn: 'Riyad as-Salihin / An-Nawawi\'s Forty Hadith',
      textId: 'Dari An-Nawwas bin Sam\'an, Nabi ﷺ bersabda: "Kebajikan adalah akhlak yang baik, dan dosa adalah apa yang bergejolak dalam dadamu dan engkau tidak suka jika orang lain mengetahuinya." Dari Wabishah bin Ma\'bad, ia berkata: Aku datang kepada Rasulullah ﷺ, lalu beliau bersabda: "Engkau datang untuk bertanya tentang kebajikan?" Aku menjawab: "Ya." Beliau bersabda: "Mintalah fatwa kepada hatimu; kebajikan adalah apa yang membuat jiwa dan hati tenteram, sedangkan dosa adalah apa yang bergejolak dalam jiwa dan membuat dada ragu, meskipun orang-orang memberimu fatwa (membolehkannya) berulang kali."',
      sourceId: 'Riyadhus Shalihin / Hadis Arbain An-Nawawi',
      textUr: 'نواس بن سمعان رضی اللہ عنہ سے روایت ہے کہ نبی ﷺ نے فرمایا: نیکی اچھے اخلاق کا نام ہے، اور گناہ وہ چیز ہے جو تمہارے دل میں کھٹکے اور تم نہ چاہو کہ لوگ اس پر مطلع ہوں۔ اور وابصہ بن معبد رضی اللہ عنہ سے روایت ہے کہ میں رسول اللہ ﷺ کے پاس آیا تو آپ ﷺ نے فرمایا: تم نیکی کے بارے میں پوچھنے آئے ہو؟ میں نے کہا جی ہاں۔ آپ ﷺ نے فرمایا: اپنے دل سے پوچھو، نیکی وہ ہے جس پر دل اور جان مطمئن ہوں، اور گناہ وہ ہے جو دل میں کھٹکے اور سینے میں تردد پیدا کرے، چاہے لوگ تمہیں بار بار فتویٰ ہی کیوں نہ دیں',
      sourceUr: 'ریاض الصالحین / اربعین نووی',
    ),
    const DhikrModel(
