      category: DhikrCategory.nawawi40,
      textEn: 'The Messenger of Allah ﷺ gave us a sermon that caused our hearts to tremble and our eyes to shed tears. We said, "O Messenger of Allah, it is as though this is a farewell sermon, so counsel us." He said, "I counsel you to be conscious of Allah, and to hear and obey even if a slave is appointed to rule over you. Whoever among you lives long will see much disagreement, so hold fast to my Sunnah and the Sunnah of the rightly-guided caliphs — cling to it firmly. And beware of newly invented matters, for every innovation is misguidance."',
      sourceEn: 'Riyad as-Salihin / An-Nawawi\'s Forty Hadith',
      textId: 'Rasulullah ﷺ memberikan nasihat kepada kami hingga hati kami bergetar dan air mata kami mengalir. Kami berkata: "Wahai Rasulullah, seakan-akan ini adalah nasihat perpisahan, maka berilah kami wasiat." Beliau bersabda: "Aku wasiatkan kepada kalian untuk bertakwa kepada Allah, serta mendengar dan taat sekalipun yang memimpin kalian seorang budak. Sesungguhnya siapa saja di antara kalian yang hidup lama akan melihat banyak perselisihan, maka berpegang teguhlah pada sunahku dan sunah para khalifah yang mendapat petunjuk, gigitlah ia dengan gigi geraham. Dan hati-hatilah kalian terhadap perkara-perkara baru (dalam agama), karena setiap perkara baru adalah bidah, dan setiap bidah adalah sesat."',
      sourceId: 'Riyadhus Shalihin / Hadis Arbain An-Nawawi',
      textUr: 'رسول اللہ ﷺ نے ہمیں ایسی نصیحت فرمائی کہ دل کانپ اٹھے اور آنکھیں بہہ پڑیں، ہم نے کہا: اے اللہ کے رسول! یہ تو الوداعی نصیحت معلوم ہوتی ہے، ہمیں وصیت فرمائیں۔ آپ ﷺ نے فرمایا: میں تمہیں اللہ سے ڈرنے اور سننے اور اطاعت کرنے کی وصیت کرتا ہوں چاہے تم پر کوئی غلام ہی حاکم کیوں نہ بنایا جائے، جو تم میں سے زندہ رہے گا وہ بہت اختلاف دیکھے گا، پس میری سنت اور ہدایت یافتہ خلفاء کی سنت کو لازم پکڑو، اسے دانتوں سے مضبوط پکڑ لو، اور نئی ایجاد کردہ باتوں سے بچو کیونکہ ہر نئی بات بدعت ہے اور ہر بدعت گمراہی ہے',
