    const DhikrModel(
      title: 'الحديث 29: أبواب الخير وأركان الدين وخطر اللسان',
      text: 'قُلْتُ: يا رَسُولَ اللَّهِ أَخْبِرْنِي بِعَمَلٍ يُدْخِلُنِي الجَنَّةَ وَيُباعِدُنِي مِنَ النّارِ، قالَ: لَقَدْ سَأَلْتَ عَنْ عَظِيمٍ، وَإِنَّهُ لَيَسِيرٌ عَلَى مَنْ يَسَّرَهُ اللَّهُ تَعالَى عَلَيْهِ: تَعْبُدُ اللَّهَ لا تُشْرِكُ بِهِ شَيْئًا، وَتُقِيمُ الصَّلاةَ، وَتُؤْتِي الزَّكاةَ، وَتَصُومُ رَمَضانَ، وَتَحُجُّ البَيْتَ. ثُمَّ قالَ: أَلا أَدُلُّكَ عَلَى أَبْوابِ الخَيْرِ؟ الصَّوْمُ جُنَّةٌ، وَالصَّدَقَةُ تُطْفِئُ الخَطِيئَةَ كَما يُطْفِئُ الماءُ النّارَ، وَصَلاةُ الرَّجُلِ فِي جَوْفِ اللَّيْلِ. ثُمَّ قالَ: أَلا أُخْبِرُكَ بِرَأْسِ الأَمْرِ وَعَمُودِهِ وَذِرْوَةِ سَنامِهِ؟ قُلْتُ: بَلَى يا رَسُولَ اللَّهِ، قالَ: رَأْسُ الأَمْرِ الإِسْلامُ، وَعَمُودُهُ الصَّلاةُ، وَذِرْوَةُ سَنامِهِ الجِهادُ. ثُمَّ قالَ: أَلا أُخْبِرُكَ بِمِلاكِ ذَلِكَ كُلِّهِ؟ قُلْتُ: بَلَى يا رَسُولَ اللَّهِ، فَأَخَذَ بِلِسانِهِ وَقالَ: كُفَّ عَلَيْكَ هَذا. قُلْتُ: يا نَبِيَّ اللَّهِ وَإِنّا لَمُؤاخَذُونَ بِما نَتَكَلَّمُ بِهِ؟ فَقالَ: ثَكِلَتْكَ أُمُّكَ يا مُعاذُ، وَهَلْ يَكُبُّ النّاسَ فِي النّارِ عَلَى وُجُوهِهِمْ -أَوْ قالَ: عَلَى مَناخِرِهِمْ- إلّا حَصائِدُ أَلْسِنَتِهِمْ.',
      source: 'عن معاذ بن جبل رضي الله عنه — رواه الترمذي وقال: حديث حسن صحيح',
      bookSource: 'الأربعون النووية للإمام النووي',
      virtue: 'أبواب الخير وأركان الدين وخطر اللسان',
      count: 1,
      category: DhikrCategory.nawawi40,
      textEn: 'I said, "O Messenger of Allah, tell me of an act that will admit me to Paradise and keep me away from the Fire." He said, "You have asked about a great matter, yet it is easy for one for whom Allah makes it easy: worship Allah, associating nothing with Him; establish prayer; pay zakat; fast Ramadan; and perform Hajj." Then he said, "Shall I not guide you to the gates of goodness? Fasting is a shield, charity extinguishes sin as water extinguishes fire, and a man\'s prayer in the depths of the night." Then he said, "Shall I not tell you of the head of the matter, its pillar, and its peak? The head of the matter is Islam, its pillar is prayer, and its peak is jihad." Then he said, "Shall I not tell you what controls all of that?" He took hold of his own tongue and said, "Restrain this." I said, "O Prophet of Allah, will we be held accountable for what we say?" He said, "May your mother grieve for you, Mu\'adh! Is there anything that topples people into the Fire on their faces, or their noses, other than the harvest of their tongues?"',
      sourceEn: 'Riyad as-Salihin / An-Nawawi\'s Forty Hadith',
      textId: 'Aku berkata: "Wahai Rasulullah, beritahu aku suatu amal yang akan memasukkanku ke surga dan menjauhkanku dari neraka." Beliau bersabda: "Sungguh engkau telah bertanya tentang perkara besar, namun itu mudah bagi orang yang dimudahkan Allah: engkau beribadah kepada Allah tanpa menyekutukan-Nya dengan sesuatu apa pun, mendirikan salat, menunaikan zakat, berpuasa Ramadan, dan berhaji ke Baitullah." Kemudian beliau bersabda: "Maukah aku tunjukkan pintu-pintu kebaikan? Puasa adalah perisai, sedekah memadamkan dosa sebagaimana air memadamkan api, dan salat seseorang di tengah malam." Kemudian beliau bersabda: "Maukah aku beritahu pokok segala perkara, tiangnya, dan puncaknya? Pokok perkara adalah Islam, tiangnya adalah salat, dan puncaknya adalah jihad." Kemudian beliau bersabda: "Maukah aku beritahu kunci dari semua itu?" Beliau memegang lidahnya sendiri dan bersabda: "Jagalah ini." Aku bertanya: "Wahai Nabi Allah, apakah kami akan diminta pertanggungjawaban atas apa yang kami ucapkan?" Beliau bersabda: "Celaka engkau wahai Mu\'adz! Bukankah tidaklah manusia dijerumuskan ke dalam neraka dengan wajah atau hidung mereka kecuali karena akibat lisan mereka?"',
      sourceId: 'Riyadhus Shalihin / Hadis Arbain An-Nawawi',
      textUr: 'میں نے کہا: اے اللہ کے رسول! مجھے ایسا عمل بتائیں جو مجھے جنت میں داخل کرے اور آگ سے دور رکھے۔ آپ ﷺ نے فرمایا: تم نے ایک بڑی بات پوچھی ہے، لیکن یہ اس کے لیے آسان ہے جس کے لیے اللہ آسان کر دے: اللہ کی عبادت کرو اور اس کے ساتھ کسی کو شریک نہ کرو، نماز قائم کرو، زکوٰۃ دو، رمضان کے روزے رکھو، اور بیت اللہ کا حج کرو۔ پھر فرمایا: کیا میں تمہیں بھلائی کے دروازے نہ بتاؤں؟ روزہ ڈھال ہے، صدقہ گناہ کو ایسے بجھا دیتا ہے جیسے پانی آگ کو بجھاتا ہے، اور آدمی کی رات کے آخری حصے میں نماز۔ پھر فرمایا: کیا میں تمہیں اس معاملے کا سر، ستون اور چوٹی نہ بتاؤں؟ میں نے کہا: ضرور اے اللہ کے رسول۔ فرمایا: اس معاملے کا سر اسلام ہے، اس کا ستون نماز ہے، اور اس کی چوٹی جہاد ہے۔ پھر فرمایا: کیا میں تمہیں اس سب کی بنیاد نہ بتاؤں؟ میں نے کہا: ضرور اے اللہ کے رسول۔ آپ ﷺ نے اپنی زبان پکڑی اور فرمایا: اسے قابو میں رکھو۔ میں نے پوچھا: اے اللہ کے نبی! کیا ہم اپنی باتوں پر پکڑے جائیں گے؟ آپ ﷺ نے فرمایا: تیری ماں تجھ پر روئے اے معاذ! لوگوں کو آگ میں اوندھے منہ کون گراتا ہے سوائے ان کی زبانوں کی کمائی کے',
